587: /** Per-resume scoring reference: group weights (points out of 100) plus the
588:  *  pass gate, mirroring matching.match_profile_to_requirements. Weights come
589:  *  live from Screening Setup when reachable, otherwise documented defaults. */
590: interface BuilderScoringRef {
591:   weights: { skills: number; experience: number; education: number; certifications: number };
592:   passingScore: number;
593:   coverageMin: number;
594:   live: boolean;
595: }
596: 
597: const DEFAULT_BUILDER_SCORING: BuilderScoringRef = {
598:   weights: { skills: 40, experience: 30, education: 20, certifications: 10 },
599:   passingScore: 75,
600:   coverageMin: 0.6,
601:   live: false,
602: };
