708: /** Back face content: every filled builder field indicated as entities. */
709: function BuilderEntitiesCard({
710:   draft,
711:   mapping,
712:   loading,
713:   error,
714:   addingTerm,
715:   scoring,
716:   onAdd,
717:   onRetry,
718:   onFlipBack,
719: }: {
720:   draft: Draft;
721:   mapping: BuilderEntityMapping | null;
722:   loading: boolean;
723:   error: string | null;
724:   addingTerm: boolean;
725:   scoring: BuilderScoringRef;
726:   onAdd: (term: string, type: "skill" | "job_role" | "certification") => void;
727:   onRetry: () => void;
728:   onFlipBack: () => void;
729: }) {
730:   const splitLines = (s: string) =>
731:     s
732:       .split("\n")
733:       .map((x) => x.trim())
734:       .filter(Boolean);
735: 
736:   const filledFields: string[] = [];
737:   if (draft.title.trim()) filledFields.push(draft.title.trim());
738:   if (draft.department.trim()) filledFields.push(draft.department.trim());
739:   if (draft.employmentType.trim()) filledFields.push(draft.employmentType.trim());
740:   if (draft.schedule.trim()) filledFields.push(draft.schedule.trim());
741:   if (draft.vacancies.trim()) filledFields.push(`${draft.vacancies.trim()} vacancies`);
742:   if (draft.salaryMin.trim() || draft.salaryMax.trim())
743:     filledFields.push(`₱${draft.salaryMin.trim() || "—"} – ₱${draft.salaryMax.trim() || "—"}`);
744: 
745:   const skillsIndex = buildBuilderEntityIndex(mapping?.skills ?? {});
746:   const rolesIndex = buildBuilderEntityIndex(mapping?.job_roles ?? {});
747:   const certsIndex = buildBuilderEntityIndex(mapping?.certifications ?? {});
748: 
749:   const skillsResult = analyzeBuilderEntityLines(splitLines(draft.skills), skillsIndex);
750:   const titleCanonical = draft.title.trim()
751:     ? canonicalizeBuilderEntity(draft.title.trim(), rolesIndex)
752:     : null;
753:   // Only certification-like lines are checked — plain sentences and skill tags
754:   // are not certificates, so showing them "to review" would invite adding
755:   // garbage to the vocabulary.
756:   const certCandidateLines = [
757:     ...splitLines(draft.qualifications),
758:     ...splitLines(draft.skills),
759:   ].filter((line) =>
760:     /nc\s*(i{1,3}|iv|1-4)|tesda|certificate|certification|license|licence|food handler/i.test(line),
761:   );
762:   const certResult = analyzeBuilderEntityLines(certCandidateLines, certsIndex);
763: 
764:   // Per-card scoring lines — simple points each indicated reference is worth
765:   // to a resume. Required skills share 70% of the skills weight; each
766:   // recognized certificate shares the certifications weight.
767:   const perSkill =
768:     skillsResult.recognized.length > 0
769:       ? (scoring.weights.skills * 0.7) / skillsResult.recognized.length
770:       : null;
771:   const perCert =
772:     certResult.recognized.length > 0
773:       ? scoring.weights.certifications / certResult.recognized.length
774:       : null;
775: 
776:   return (
777:     <div className="space-y-3">
778:       <div className="flex items-center justify-between gap-2">
779:         <h2 className="flex items-center gap-2 font-display text-xl font-semibold">
780:           <ScanLine className="h-4 w-4 text-primary" /> Entities Indicated
781:         </h2>
782:         <Button type="button" size="sm" variant="outline" onClick={onFlipBack}>
783:           <Repeat className="mr-1.5 h-3.5 w-3.5" /> Back to editing
784:         </Button>
785:       </div>
786:       <p className="text-[0.7rem] text-muted-foreground">
787:         Whatever is filled in the builder inputs and dropdowns, indicated as screening entities.
788:         Recognized terms match resumes — others are flagged until added to the vocabulary.
789:       </p>
790: 
791:       {loading ? (
792:         <p className="flex items-center gap-2 rounded-md border border-dashed border-border px-3 py-4 text-xs text-muted-foreground">
793:           <Loader2 className="h-4 w-4 animate-spin" /> Loading screening vocabulary…
794:         </p>
795:       ) : error ? (
796:         <div className="space-y-2 rounded-md border border-destructive/30 bg-destructive/5 p-3">
