export default async function run(page) {
  const out = {}
  const txt = (s) => page.locator(s).innerText()
  const count = (s) => page.locator(s).count()

  // ---- 1. initial state: template auto-applied, chips rendered ----
  out.initial = {
    banner: await txt('#tplBanner'),
    skillChips: await count('#skillChips .chip'),
    certChips: await count('#certChips .chip'),
    recognized: await count('#skillChips .chip.ok'),
    unrecognized: await count('#skillChips .chip.bad'),
    gate: await txt('#gate'),
    edu: await page.locator('#edu').inputValue(),
  }

  // ---- 2. publish blocked when 0 recognized skills ----
  // remove every recognized skill, leave only unrecognized ones
  await page.evaluate(() => {
    STATE.skills = ['Something nobody recognises']
    render()
  })
  out.blockedGate = await txt('#gate')
  await page.locator('#gate').waitFor()

  // ---- 3. + on an unrecognized chip adds it to the vocabulary -> publish unblocks ----
  await page.locator('#skillChips .chip.bad .plus').first().click()
  out.afterPlus = {
    gate: await txt('#gate'),
    recognized: await count('#skillChips .chip.ok'),
  }

  // ---- 4. remove chip via × ----
  await page.locator('#skillChips .chip.ok .x').first().click()
  out.afterRemove = { skillChips: await count('#skillChips .chip') }

  // ---- 5. auto-apply on a clean draft (no confirm dialog) ----
  await page.evaluate(() => { STATE.skills = []; STATE.certs = []; STATE.tpl = null; render() })
  await page.locator('#pos').selectOption('lc')
  out.autoApply = {
    veilOpen: await page.locator('#veil').evaluate((e) => e.classList.contains('on')),
    banner: await txt('#tplBanner'),
    skills: await count('#skillChips .chip'),
    certs: await count('#certChips .chip'),
    edu: await page.locator('#edu').inputValue(),
    srcTag: await txt('#srcTag'),
  }

  // ---- 6. confirm dialog appears when skills already exist ----
  await page.locator('#pos').selectOption('fdo')
  out.confirm = {
    veilOpen: await page.locator('#veil').evaluate((e) => e.classList.contains('on')),
    title: await txt('#dlgTpl'),
    diff: await txt('#dlgDiff'),
  }

  // ---- 7. cancel keeps existing requirements ----
  await page.locator('.dlg .btn.ghost').click()
  out.afterCancel = {
    veilOpen: await page.locator('#veil').evaluate((e) => e.classList.contains('on')),
    banner: await txt('#tplBanner'),
  }

  // ---- 8. accept replaces ----
  await page.locator('#pos').selectOption('fdo')
  await page.locator('.dlg .btn:not(.ghost)').click()
  out.afterReplace = { banner: await txt('#tplBanner'), skills: await count('#skillChips .chip') }

  // ---- 9. position with NO template -> empty state ----
  await page.locator('#pos').selectOption('hr')
  out.noTemplate = {
    banner: await txt('#tplBanner'),
    srcTag: await txt('#srcTag'),
    skills: await count('#skillChips .chip'),
  }

  // ---- 10. combobox filters and adds ----
  await page.locator('#skillChips button').first().click()
  await page.locator('#skillInput').fill('guest')
  out.comboOptions = await count('#skillOptions .opt')
  await page.locator('#skillOptions .opt').first().click()
  out.afterAdd = { skills: await count('#skillChips .chip'), gate: await txt('#gate') }

  // ---- 11. BEFORE tab renders ----
  await page.locator('#tab-before').click()
  out.beforeVisible = await page.locator('#view-before').isVisible()

  out.consoleClean = true
  return out
}

export default async function run(page) {
  const out = {}
  const txt = (s) => page.locator(s).innerText()
  const count = (s) => page.locator(s).count()
  const veilOpen = () => page.locator('#veil').evaluate((e) => e.classList.contains('on'))

  // Remove every chip by clicking its × until none are left.
  async function removeAllChips() {
    for (let i = 0; i < 40; i++) {
      const n = await count('#skillChips .chip .x')
      if (n === 0) break
      await page.locator('#skillChips .chip .x').last().click()
    }
  }

  // ---- 1. boot: template auto-applied, chips rendered ----
  out.boot = {
    banner: (await txt('#tplBanner')).replace(/\s+/g, ' '),
    skillChips: await count('#skillChips .chip'),
    certChips: await count('#certChips .chip'),
    recognized: await count('#skillChips .chip.ok'),
    unrecognized: await count('#skillChips .chip.bad'),
    edu: await page.locator('#edu').inputValue(),
    gate: (await txt('#gate')).replace(/\s+/g, ' '),
  }

  // ---- 2. publish gate blocks when 0 skills are recognised ----
  await removeAllChips()
  await page.locator('#skillChips .chip').first().waitFor().catch(() => {})
  out.gateEmpty = (await txt('#gate')).replace(/\s+/g, ' ')

  // ---- 3. "+" on an unrecognized chip adds it to the vocabulary ----
  // (with no chips at all, add one via the empty-state button)
  await page.locator('#skillChips button').first().click()
  await page.locator('#skillInput').fill('zzz not a real skill')
  await page.locator('#skillOptions .opt .btn').click()
  out.afterManualAdd = {
    chips: await count('#skillChips .chip'),
    gate: (await txt('#gate')).replace(/\s+/g, ' '),
  }

  // ---- 4. "+" converts an unrecognized chip to recognized ----
  await page.locator('#skillChips .chip.bad .plus').first().click()
  out.afterPlus = {
    recognized: await count('#skillChips .chip.ok'),
    gate: (await txt('#gate')).replace(/\s+/g, ' '),
  }

  // ---- 5. auto-apply on a clean draft: no dialog ----
  await removeAllChips()
  await page.locator('#pos').selectOption('lc')
  out.autoApply = {
    veilOpen: await veilOpen(),
    banner: (await txt('#tplBanner')).replace(/\s+/g, ' '),
    skills: await count('#skillChips .chip'),
    certs: await count('#certChips .chip'),
    edu: await page.locator('#edu').inputValue(),
    exp: await page.locator('#exp').inputValue(),
    srcTag: await txt('#srcTag'),
  }

  // ---- 6. confirm dialog when requirements already exist ----
  await page.locator('#pos').selectOption('fdo')
  out.confirm = {
    veilOpen: await veilOpen(),
    template: await txt('#dlgTpl'),
    position: await txt('#dlgPos'),
    diff: (await txt('#dlgDiff')).replace(/\s+/g, ' '),
  }

  // ---- 7. cancel keeps what was already there ----
  await page.locator('.dlg .btn.ghost').click()
  out.afterCancel = {
    veilOpen: await veilOpen(),
    banner: (await txt('#tplBanner')).replace(/\s+/g, ' '),
    skills: await count('#skillChips .chip'),
  }

  // ---- 8. accept replaces ----
  await page.locator('#pos').selectOption('fdo')
  await page.locator('.dlg .btn').last().click()
  out.afterReplace = {
    banner: (await txt('#tplBanner')).replace(/\s+/g, ' '),
    skills: await count('#skillChips .chip'),
  }

  // ---- 9. position with NO template -> empty state ----
  await page.locator('#pos').selectOption('hr')
  out.noTemplate = {
    banner: (await txt('#tplBanner')).replace(/\s+/g, ' '),
    srcTag: await txt('#srcTag'),
    skills: await count('#skillChips .chip'),
  }

  // ---- 10. combobox filters ----
  await page.locator('#skillChips button').first().click()
  await page.locator('#skillInput').fill('guest')
  out.comboFiltered = await count('#skillOptions .opt')
  await page.locator('#skillOptions .opt').first().click()
  out.afterComboAdd = {
    skills: await count('#skillChips .chip'),
    gate: (await txt('#gate')).replace(/\s+/g, ' '),
  }

  // ---- 11. BEFORE tab ----
  await page.locator('#tab-before').click()
  out.beforeVisible = await page.locator('#view-before').isVisible()

  return out
}

