    toast('Requirements applied from <b>'+esc(tpl.name)+'</b>');
    return;
  }
  pendingTpl=tpl; pendingPos=posLabel;       /* otherwise ask first */
  openConfirm();
}

function applyTemplate(tpl){
  STATE.tpl=tpl;
  STATE.skills=tpl.skills.slice();
  STATE.certs=tpl.certs.slice();
  document.getElementById('edu').value=tpl.edu;
  document.getElementById('exp').value=tpl.exp;
  render();
}

