function gate(){
  var total=STATE.skills.length;
  var okCount=STATE.skills.filter(function(s){return vocabHit(s,VOCAB.skills);}).length;
  var el=document.getElementById('gate');
  var N=function(n,w){return n+' '+w+(n===1?'':'s');};
  if(total===0){
    el.innerHTML='<div class="note err"><b>Publish blocked.</b> This post has no required skills, so the '
      +'Skills criterion would score 0 of 40 for every applicant. Add skills below.</div>';
  }else if(okCount===0){
    el.innerHTML='<div class="note err"><b>Publish blocked.</b> 0 of '+total+' skills are recognized by the '
      +'screening model, so nothing would match a resume. Add at least one vocabulary skill, '
      +'or mark a term with <b>+</b> to add it to the vocabulary.</div>';
  }else if(okCount<total){
    /* The gate is computed against every required skill that publishes, exactly
       like matching.py — so the ask must name the unrecognized ones. */
    var bad=STATE.skills.filter(function(s){return !vocabHit(s,VOCAB.skills);});
    var need=Math.ceil(total*0.6);
    el.innerHTML='<div class="note warn"><b>Ready to publish</b> — '+okCount+' of '+total+' skills recognized ('
      +Math.round(okCount/total*100)+'%). A resume must match at least '+need+' of these '+total+' to pass.<br/>'
      +'Unrecognized, so they will not match resumes: <b>'+esc(bad.join(', '))+'</b></div>';
  }else{
    var need2=Math.ceil(total*0.6);
    el.innerHTML='<div class="note info"><b>Ready to publish.</b> All '+N(okCount,'skill')+' recognized. '
      +'Coverage gate is 60% — a resume must match at least '+need2+' of these '+total+' to pass.</div>';
  }
}

