export default async function run(page) {
  const out = {}
  const txt = (s) => page.locator(s).innerText()
  const count = (s) => page.locator(s).count()
  const flat = (s) => (s || '').replace(/\s+/g, ' ').trim()
  const panel = () => txt('#panel')

  // ---- step 1: nothing enabled before a position is chosen ----
  out.step1_initial = {
    continueDisabled: await page.locator('.foot .btn:not(.ghost)').isDisabled(),
    hasDropdown: await count('#posSel'),
  }

  // ---- choose the templated position ----
  await page.locator('#posSel').selectOption('fdo')
  out.step1_chosen = {
    continueEnabled: !(await page.locator('.foot .btn:not(.ghost)').isDisabled()),
    panel: flat(await panel()),
  }

  await page.locator('.foot .btn:not(.ghost)').click()

  // ---- step 2: template auto-applied ----
  out.step2 = {
    banner: flat(await txt('.note')),
    skillChips: await count('.chip.ok'),
    unrecognized: await count('.chip.bad'),
    stepTitle: await txt('h2.sec'),
  }

  await page.locator('.foot .btn:not(.ghost)').click()

  // ---- step 3: live findings ----
  out.step3_findings = {
    total: await count('#findings .finding'),
    fresh: await count('#findings .finding.hit, #findings .finding.cert'),
    duplicates: await count('#findings .finding.dup'),
    text: flat(await txt('#findings')),
  }

  // ---- "Move to requirements" keeps the prose line ----
  const respBefore = await page.locator('#t-resp').inputValue()
  await page.getByRole('button', { name: 'Move to requirements' }).first().click()
  out.moveKeepLine = {
    respUnchanged: (await page.locator('#t-resp').inputValue()) === respBefore,
    toast: flat(await txt('#toast')),
  }

  // ---- "Move & delete the line" removes the duplicate prose ----
  const respBefore2 = await page.locator('#t-resp').inputValue()
  const btn = page.getByRole('button', { name: 'Move & delete the line' }).first()
  const had = await btn.count()
  if (had) await btn.click()
  out.moveDeleteLine = {
    respChanged: (await page.locator('#t-resp').inputValue()) !== respBefore2,
    toast: flat(await txt('#toast')),
  }

  // ---- typing a new skill is detected live ----
  await page.locator('#t-resp').fill('Welcome and assist hotel guests.\nKnife Skills\nSome prose line.')
  await page.waitForTimeout(150)
  out.liveDetect = {
    findings: flat(await txt('#findings')),
  }

  // ---- a requirement-shaped but unknown line is flagged differently ----
  await page.locator('#t-resp').fill('Must be able to work in a fast-paced environment')
  await page.waitForTimeout(150)
  out.unknownFlag = flat(await txt('#findings'))

  await page.locator('.foot .btn:not(.ghost)').click()

  // ---- step 4: review ----
  out.step4 = {
    panel: flat(await panel()),
    gate: flat(await txt('#note.warn, .note.good, .note.err')),
    publishDisabled: await page.locator('.foot .btn:not(.ghost)').isDisabled(),
  }

  // ---- the no-template position offers suggestions ----
  await page.locator('.foot .btn.ghost').click() // back to writing
  await page.locator('.foot .btn.ghost').click() // back to requirements
  await page.locator('.foot .btn.ghost').click() // back to position
  await page.locator('#posSel').selectOption('hr')
  await page.locator('.foot .btn:not(.ghost)').click()
  out.noTemplate = {
    banner: flat(await txt('.note.warn')),
    suggestionCount: await count('.sug'),
    suggestionPanel: flat(await txt('.sug')),
    skillChips: await count('.chip.ok'),
  }

  // ---- clicking a suggestion adds it ----
  await page.locator('.sug').first().click()
  out.afterSuggestion = {
    chipAdded: await count('.chip.ok'),
  }

  await page.locator('.foot .btn:not(.ghost)').click()
  await page.locator('.foot .btn:not(.ghost)').click()
  out.reviewAfterSuggestion = {
    gate: flat(await txt('.note.warn, .note.good, .note.err')),
    publishDisabled: await page.locator('.foot .btn:not(.ghost)').isDisabled(),
    summary: flat(await panel()),
  }

  return out
}

