export default async function run(page) {
  await page.locator('#posSel').selectOption('fdo')
  await page.locator('.foot .btn:not(.ghost)').click()
  await page.locator('.foot .btn:not(.ghost)').click()
  await page.locator('#t-resp').fill(
    'Welcome and assist hotel guests.\nKnife Skills\nManage room reservations.\nMust be able to work in a fast-paced environment'
  )
  await page.waitForTimeout(250)
  return { findings: await page.locator('#findings .finding').count() }
}

