export default async function run(page) {
  const out = {}
  const flat = (s) => (s || '').replace(/\s+/g, ' ').trim()
  const count = (s) => page.locator(s).count()
  const gate = () => flat(page.locator('#gate').innerText())

  // ---- boot: no Required Skills block anywhere ----
  out.blocks = (await page.locator('#canvas .bhead').allInnerTexts()).map(flat)
  out.hasSkillsBlock = out.blocks.some((b) => /required skills/i.test(b))

  // ---- Job Info still holds the two structured dropdowns ----
  out.jobInfo = {
    edu: await page.locator('[data-field="educationLevel"]').count(),
    exp: await page.locator('[data-field="experienceLevel"]').count(),
    eduLockedLabel: flat(await page.locator('text=Never free text').first().innerText()),
  }

  // ---- derivation from the seeded prose ----
  out.bootDerived = {
    gate: await gate(),
    publishDisabled: await page.locator('#publish').isDisabled(),
    derived: flat(await page.locator('.derived').innerText()),
  }

  // ---- per-line feedback under Responsibilities / Qualifications ----
  out.respLines = await count('[data-lines="responsibilities"] .line')
  out.qualLines = await count('[data-lines="qualifications"] .line')
  out.qualKinds = {
    skill: await count('[data-lines="qualifications"] .line.skill'),
    cert: await count('[data-lines="qualifications"] .line.cert'),
    dead: await count('[data-lines="qualifications"] .line.dead'),
  }

  // ---- typing a line that matches nothing shows a "dead" line ----
  await page.locator('[data-field="responsibilities"]').fill(
    'Welcome and assist hotel guests.\nHandle guest inquiries and complaints professionally.\nManage the fast-paced environment'
  )
  await page.waitForTimeout(200)
  out.afterDeadLine = {
    dead: await count('[data-lines="responsibilities"] .line.dead'),
    gate: await gate(),
  }

  // ---- typing recognised skills raises the derived count live ----
  await page.locator('[data-field="responsibilities"]').fill(
    'Welcome and assist hotel guests.\nCash Handling\nReservations\nPlating'
  )
  await page.waitForTimeout(200)
  out.afterTypingSkills = {
    derived: flat(await page.locator('.derived').innerText()),
    gate: await gate(),
    publishDisabled: await page.locator('#publish').isDisabled(),
  }

  // ---- "+" adds an unrecognized canonical to the vocabulary ----
  // "Hospitality Mindset" is not in VOCAB, so adding it turns a dead line live
  await page.locator('[data-field="qualifications"]').fill('Hospitality Mindset')
  await page.waitForTimeout(200)
  out.vocabBefore = await count('[data-lines="qualifications"] .line.dead')
  await page.locator('[data-act="addVocab"]').first().click()
  await page.waitForTimeout(200)
  out.vocabAfter = await count('[data-lines="qualifications"] .line.skill')
  out.toast = flat(await page.locator('#toast').innerText())

  // ---- load an existing published post: its skills_json survives ----
  await page.locator('#loadExisting').click()
  await page.waitForTimeout(200)
  out.existingPost = {
    toast: flat(await page.locator('#toast').innerText()),
    qualText: await page.locator('[data-field="qualifications"]').inputValue(),
    derived: flat(await page.locator('.derived').innerText()),
  }

  // ---- picking a position auto-seeds from the template ----
  await page.locator('#posSel').selectOption('lc')
  await page.waitForTimeout(250)
  out.pickPosition = {
    edu: await page.locator('[data-field="educationLevel"]').inputValue(),
    exp: await page.locator('[data-field="experienceLevel"]').inputValue(),
    derived: flat(await page.locator('.derived').innerText()),
    gate: await gate(),
  }

  // ---- position with no template ----
  await page.locator('#posSel').selectOption('hr')
  await page.waitForTimeout(200)
  out.noTemplate = { derived: flat(await page.locator('.derived').innerText()) }

  return out
}

