function pickPosition(key){
  var prevTemplate=S.templateName;          /* capture BEFORE overwriting */
  S.posKey=key; S.pos=POSITIONS[key];
  var t=TEMPLATES[key];
  S.templateName=t?t.name:null;
  if(t){
    /* auto-seed on a clean draft or when switching to a different template,
       same "ask before overwriting" guard the salary sync uses */
    if(!splitLines(S.qualifications).length || prevTemplate!==t.name){
      S.qualifications=splitLines(S.qualifications)
        .concat(t.skills).concat(t.certs).join("\n");
      S.educationLevel=t.edu; S.experienceLevel=t.exp;
    }
  }
  render();
}

