.ai{border:1px solid var(--border);border-radius:10px;padding:13px;margin-top:13px;
  background:color-mix(in oklch,var(--secondary) 22%,var(--card))}
.aihead{display:flex;justify-content:space-between;align-items:flex-start;gap:12px}
.airow{display:grid;grid-template-columns:190px 1fr;gap:10px;align-items:center;
  padding:6px 0;border-top:1px solid color-mix(in oklch,var(--border) 70%,transparent)}
.airow:first-of-type{border-top:0}
.airow.off{opacity:.5}
.cb{display:flex;align-items:center;gap:8px;font-size:12.5px;font-weight:600;cursor:pointer}
.cb input{width:auto;margin:0;accent-color:var(--primary)}
.ainote{font-size:12px}
.ainote::placeholder{color:var(--muted-fg);opacity:.7}
.aiout{margin-top:11px;border-top:1px solid var(--border);padding-top:11px;display:none}
.aiout.on{display:block}
.aiout .r{display:flex;gap:8px;align-items:baseline;font-size:12px;padding:3px 0}
.aiout .r .k{width:120px;flex-shrink:0;color:var(--muted-fg)}
.aiout .r .v{color:var(--foreground)}
.aiout ul{margin:4px 0 0;padding-left:18px;font-size:12px}
.limits{font-size:11px;color:var(--muted-fg);margin-top:8px;display:flex;
  justify-content:space-between;align-items:center;gap:10px;flex-wrap:wrap}
.meter{display:inline-flex;gap:3px;vertical-align:middle}
.meter i{width:16px;height:5px;border-radius:3px;background:var(--muted);display:block}
.meter i.used{background:var(--primary)}
.meter i.full{background:var(--caution)}
.hidden{display:none !important}

