/* ---------- AI: checklist-driven generation ---------------------------- */
/* Mirrors the real call chain: the browser sends ONLY the ticked fields plus
   their notes, the backend injects the screening vocabulary, and the reply is
   checked against that vocabulary so HR sees which terms actually match. */

var AI_FIELDS = ["position","department","skills","certificate","education","experience"];

function aiSelection(){
  var picked={}, notes={};
  AI_FIELDS.forEach(function(f){
    var box=document.querySelector('[data-ai="'+f+'"]');
    var note=document.querySelector('[data-note="'+f+'"]');
    picked[f]=!!(box&&box.checked);
    notes[f]=(note&&note.value||"").trim();
  });
  return {picked:picked,notes:notes};
}

function aiSyncRows(){
  var sel=aiSelection();
  AI_FIELDS.forEach(function(f){
    var row=document.querySelector('[data-row="'+f+'"]');
    if(row) row.classList.toggle("off",!sel.picked[f]);
  });
  var any=AI_FIELDS.some(function(f){return sel.picked[f];});
  var go=document.getElementById("aiGo");
  if(go) go.disabled=!any;
}

/** What the AI returns. Deliberately includes one term that is NOT in the
 *  vocabulary, so the grounding report has something real to say. */
function aiMockResponse(sel){
  var key=STATE.pos||"fdo";
  var n=sel.notes;
  var out={};

  if(sel.picked.skills){
    var base = key==="lc"
      ? ["Food Safety","Knife Skills","Plating"]
      : ["Front Office Operations","Guest Relations","Complaint Handling","Scheduling"];
    /* the notes box steers the mock the way it would steer the real model */
    if(/technical|software|excel|ms office/i.test(n.skills))
      base=["MS Office","Time Management","Scheduling"];
    else if(/guest|service|front/i.test(n.skills))
      base=["Customer Service","Guest Relations","Complaint Handling","Front Office Operations"];
    /* one invented term, to demonstrate skills_new */
    out.skills=base.concat(["Service Upselling"]);
  }
  if(sel.picked.certificate){
    out.certs = key==="lc" ? ["TESDA NC II Cookery","Food Handler Certificate"] : ["TESDA NC II Front Office"];
  }
  if(sel.picked.education){
    out.edu = /any bachelor|accept any/i.test(n.education) ? "Bachelor's Degree" : "College Level";
  }
  if(sel.picked.experience){
    out.exp = /hotel experience|strongly preferred/i.test(n.experience) ? "3-5 Years" : "1-2 Years";
  }
  out.positionNote = n.position ? "Position guidance applied: "+n.position : "";
  out.deptNote    = n.department ? "Department guidance applied: "+n.department : "";
  return out;
}

function aiGenerate(){
  var sel=aiSelection();
  if(!AI_FIELDS.some(function(f){return sel.picked[f];})) return;

  var res=aiMockResponse(sel);
  var rows=[], fresh=[];

  /* apply to the draft exactly where each value belongs */
  if(res.skills){
    var addedSk=[], matchedSk=[];
    res.skills.forEach(function(s){
      var c=vocabHit(s,VOCAB.skills);
      if(!c){ fresh.push(s); addedSk.push(s); return; }
      if(STATE.skills.map(function(x){return x.toLowerCase();}).indexOf(c.toLowerCase())<0) addedSk.push(c);
      matchedSk.push(c);
    });
    if(addedSk.length) STATE.skills=STATE.skills.concat(addedSk);
    rows.push({k:"Skills",v:addedSk.length+" added to Screening Requirements",
      list:addedSk.map(function(s){
        return vocabHit(s,VOCAB.skills)
          ? "&#10003; "+esc(s)+" <span class='muted'>(already in vocabulary)</span>"
          : "&#9679; "+esc(s)+" <span class='muted'>&mdash; new, press + to add to the vocabulary</span>";
      })});
  }
  if(res.certs && res.certs.length){
    var addedC=[];
    res.certs.forEach(function(c){
      if(STATE.certs.map(function(x){return x.toLowerCase();}).indexOf(c.toLowerCase())<0) addedC.push(c);
    });
    STATE.certs=STATE.certs.concat(addedC);
    rows.push({k:"Certificates",v:addedC.length+" added"});
  }
  if(res.edu && sel.picked.education){
    STATE.edu=res.edu;
    var e=document.getElementById("edu"); if(e) e.value=res.edu;
    rows.push({k:"Education",v:esc(res.edu)});
  }
  if(res.exp && sel.picked.experience){
    STATE.exp=res.exp;
    var x2=document.getElementById("exp"); if(x2) x2.value=res.exp;
    rows.push({k:"Experience",v:esc(res.exp)});
  }

  render();

  /* the grounding report — the whole point of passing the vocabulary in */
  var html=rows.map(function(r){
    return '<div class="r"><span class="k">'+esc(r.k)+'</span><span class="v">'+r.v
      +(r.list?'<ul>'+r.list.map(function(li){return "<li>"+li+"</li>";}).join("")+"</ul>":"")
      +'</span></div>';
  }).join("");

  if(!sel.picked.position && !sel.picked.department){
    html+='<div class="r"><span class="k">Not generated</span><span class="v muted">'
      +'you unticked Position and Department, so the AI left them alone</span></div>';
  }
  html+='<div class="r" style="margin-top:6px"><span class="k">Skipped</span><span class="v muted">'
    +AI_FIELDS.filter(function(f){return !sel.picked[f];}).map(function(f){return f;}).join(", ")
    +'</span></div>';

  var out=document.getElementById("aiOut");
  out.innerHTML=html;
  out.classList.add("on");

  var m=document.getElementById("aiMeter");
  if(m){
    var i=m.querySelectorAll("i");
    [].forEach.call(i,function(el,idx){ el.className = idx<3 ? "used full" : ""; });
  }
  toast(fresh.length
    ? "<b>AI draft ready</b> — "+fresh.length+" term(s) not in your vocabulary. Add them with + so resumes match."
    : "<b>AI draft ready</b> — every generated term is already in your vocabulary.",
    fresh.length?"warn":"good");
}

document.addEventListener("click",function(e){
  var b=e.target.closest("[data-act='aiGenerate']");
  if(b) aiGenerate();
});
document.addEventListener("change",function(e){
  if(e.target.closest && e.target.closest("[data-ai]")) aiSyncRows();
});
document.addEventListener("input",function(e){
  if(e.target.closest && e.target.closest("[data-note]")) aiSyncRows();
});

/* ---------- reset / view ---------- */

