export default async function run(page) {
  const out = {}
  const flat = (s) => (s || '').replace(/\s+/g, ' ').trim()
  const count = (s) => page.locator(s).count()
  const aiOut = async () => flat(await page.locator('#aiOut').innerText())

  // ---- checklist present with a notes box per row ----
  out.rows = []
  for (const f of ['position','department','skills','certificate','education','experience']) {
    out.rows.push({
      field: f,
      checkbox: await page.locator(`[data-ai="${f}"]`).count(),
      note: await page.locator(`[data-note="${f}"]`).count(),
    })
  }

  // ---- unticking everything disables Generate ----
  for (const f of ['position','department','skills','certificate','education','experience']) {
    await page.locator(`[data-ai="${f}"]`).uncheck()
  }
  out.allUnchecked = {
    generateDisabled: await page.locator('#aiGo').isDisabled(),
    dimmedRows: await count('.airow.off'),
  }

  // ---- ticking only Skills works ----
  await page.locator('[data-ai="skills"]').check()
  out.onlySkills = {
    generateDisabled: await page.locator('#aiGo').isDisabled(),
    dimmedRows: await count('.airow.off'),
  }
  await page.locator('#aiGo').click()
  await page.waitForTimeout(200)
  out.resultOnlySkills = { aiOut: await aiOut() }

  // ---- full run: all ticked, notes steer the result ----
  for (const f of ['position','department','education','experience','certificate']) {
    await page.locator(`[data-ai="${f}"]`).check()
  }
  await page.locator('#aiGo').click()
  await page.waitForTimeout(200)
  out.fullRun = {
    aiOut: await aiOut(),
    toast: flat(await page.locator('#toast').innerText()),
    edu: await page.locator('#edu').inputValue(),
    exp: await page.locator('#exp').inputValue(),
  }

  // ---- the notes box actually steers the generated skills ----
  await page.locator('[data-note="skills"]').fill('skip anything technical, use excel instead')
  await page.locator('#aiGo').click()
  await page.waitForTimeout(200)
  out.notesSteer = await aiOut()

  // ---- education note steers the education result ----
  await page.locator('[data-note="education"]').fill('accept any bachelor degree')
  await page.locator('#aiGo').click()
  await page.waitForTimeout(200)
  out.eduNote = {
    edu: await page.locator('#edu').inputValue(),
    out: await aiOut(),
  }

  // ---- unticked fields are reported as skipped, never written ----
  await page.locator('[data-ai="skills"]').uncheck()
  await page.locator('[data-ai="certificate"]').uncheck()
  await page.locator('#aiGo').click()
  await page.waitForTimeout(200)
  out.unticked = await aiOut()

  // ---- the generated skills landed in the requirements panel ----
  out.panel = {
    skillChips: await count('#skillChips .chip'),
    unrecognized: await count('#skillChips .chip.bad'),
    certChips: await count('#certChips .chip'),
  }

  return out
}

