export default async function run(page) {
  const out = {}
  const flat = (s) => (s || '').replace(/\s+/g, ' ').trim()
  const count = (s) => page.locator(s).count()
  const veil = () => page.locator('#aiVeil').evaluate((e) => e.classList.contains('on'))
  const aiOut = async () => flat(await page.locator('#aiOut').innerText())

  // ---- closed at boot: the checklist is NOT on the page ----
  out.boot = {
    modalOpen: await veil(),
    openButton: await count('[data-act="aiOpen"]'),
    checkboxesVisible: await count('[data-ai="position"]'),
  }
  out.boot.modalHidden = !(await page.locator('#aiVeil').isVisible())

  // ---- clicking the button opens the modal ----
  await page.locator('[data-act="aiOpen"]').click()
  await page.waitForTimeout(150)
  out.opened = {
    modalOpen: await veil(),
    visible: await page.locator('#aiVeil').isVisible(),
    rows: await count('#aiVeil .airow'),
    notes: await count('#aiVeil [data-note]'),
    generateBtn: await page.locator('#aiGo').isVisible(),
  }

  // ---- untick all disables Generate ----
  for (const f of ['position','department','skills','certificate','education','experience']) {
    await page.locator(`[data-ai="${f}"]`).uncheck()
  }
  out.allUnchecked = {
    generateDisabled: await page.locator('#aiGo').isDisabled(),
    dimmedRows: await count('#aiVeil .airow.off'),
  }

  // ---- tick only Skills, generate ----
  await page.locator('[data-ai="skills"]').check()
  await page.locator('#aiGo').click()
  await page.waitForTimeout(200)
  out.onlySkills = {
    aiOut: await aiOut(),
    toast: flat(await page.locator('#toast').innerText()),
  }

  // ---- full run with notes ----
  for (const f of ['position','department','certificate','education','experience']) {
    await page.locator(`[data-ai="${f}"]`).check()
  }
  await page.locator('[data-note="education"]').fill('accept any bachelor degree')
  await page.locator('#aiGo').click()
  await page.waitForTimeout(200)
  out.fullRun = {
    aiOut: await aiOut(),
    edu: await page.locator('#edu').inputValue(),
  }

  // ---- Escape closes ----
  await page.keyboard.press('Escape')
  await page.waitForTimeout(150)
  out.afterEscape = { modalOpen: await veil() }

  // ---- reopening then backdrop click closes ----
  await page.locator('[data-act="aiOpen"]').click()
  await page.waitForTimeout(120)
  out.reopened = await veil()
  await page.locator('#aiVeil').click({ position: { x: 5, y: 5 } })
  await page.waitForTimeout(150)
  out.afterBackdrop = await veil()

  // ---- close button ----
  await page.locator('[data-act="aiOpen"]').click()
  await page.waitForTimeout(120)
  await page.locator('[data-act="aiClose"]').click()
  await page.waitForTimeout(150)
  out.afterCloseBtn = await veil()

  // ---- results were applied to the draft even after closing ----
  out.applied = {
    skillChips: await count('#skillChips .chip'),
    unrecognized: await count('#skillChips .chip.bad'),
    certChips: await count('#certChips .chip'),
    edu: await page.locator('#edu').inputValue(),
  }

  return out
}

