export default async function run(page) {
  const out = {}
  const flat = (s) => (s || '').replace(/\s+/g, ' ').trim()
  const count = (s) => page.locator(s).count()
  const aiOut = async () => flat(await page.locator('#aiOut').innerText())

  // ---- block order on the canvas ----
  out.blocks = (await page.locator('.canvas .bhead').allInnerTexts()).map(flat)
  out.additionalIndex = out.blocks.findIndex((b) => /Additional Info/.test(b))
  out.qualIndex = out.blocks.findIndex((b) => /^⠿Qualifications/.test(b))
  out.belowQualifications = out.additionalIndex === out.qualIndex + 1
  out.blockExists = await count('#addInfo')

  // ---- checklist row present ----
  out.checklist = {
    checkbox: await count('[data-ai="additional"]'),
    note: await count('[data-note="additional"]'),
    rows: await count('#aiVeil .airow'),
  }

  // ---- untick Additional Info only: it must not be generated ----
  await page.locator('[data-act="aiOpen"]').click()
  await page.waitForTimeout(150)
  await page.locator('[data-ai="additional"]').uncheck()
  await page.locator('#aiGo').click()
  await page.waitForTimeout(200)
  out.unticked = {
    out: await aiOut(),
    addInfoValue: await page.locator('#addInfo').inputValue(),
  }

  // ---- tick it: fills the block ----
  await page.locator('[data-ai="additional"]').check()
  await page.locator('#aiGo').click()
  await page.waitForTimeout(200)
  out.ticked = {
    out: await aiOut(),
    addInfoValue: await page.locator('#addInfo').inputValue(),
  }

  // ---- the notes box steers it ----
  await page.locator('[data-note="additional"]').fill('focus on night shift perks only')
  await page.locator('#aiGo').click()
  await page.waitForTimeout(200)
  out.notesSteer = {
    addInfoValue: await page.locator('#addInfo').inputValue(),
  }

  // ---- untick everything else: Additional Info alone still works ----
  for (const f of ['position','department','skills','certificate','education','experience']) {
    await page.locator(`[data-ai="${f}"]`).uncheck()
  }
  await page.locator('#aiGo').click()
  await page.waitForTimeout(200)
  out.onlyAdditional = await aiOut()

  return out
}

