export default async function run(page) {
  const out = {}
  const flat = (s) => (s || '').replace(/\s+/g, ' ').trim()
  const cb = page.locator('[data-ai="additional"]')

  await page.locator('[data-act="aiOpen"]').click()
  await page.waitForTimeout(150)

  out.initial = await cb.isChecked()
  await cb.uncheck()
  out.afterUncheck = await cb.isChecked()
  await page.locator('#aiGo').click()
  await page.waitForTimeout(200)
  out.afterFirstRun = { checked: await cb.isChecked(), out: flat(await page.locator('#aiOut').innerText()) }

  await cb.check()
  out.afterCheck = await cb.isChecked()

  // is the modal still open / is the element the same node?
  out.modalOpen = await page.locator('#aiVeil').evaluate((e) => e.classList.contains('on'))
  out.matches = await page.locator('[data-ai="additional"]').count()

  await page.locator('#aiGo').click()
  await page.waitForTimeout(200)
  out.afterSecondRun = {
    checked: await cb.isChecked(),
    out: flat(await page.locator('#aiOut').innerText()),
    addInfo: await page.locator('#addInfo').inputValue(),
  }
  return out
}

