input.content:
export default async function run(page) {
  const cb = page.locator('[data-ai="additional"]')
  const veil = page.locator('#aiVeil')

  await page.locator('[data-act="aiOpen"]').click()
  await page.waitForTimeout(150)
  await cb.uncheck()
  await page.locator('#aiGo').click()
  await page.waitForTimeout(150)
  await cb.check()
  await page.locator('#aiGo').click()
  await page.waitForTimeout(200)

  return {
    fields: await veil.getAttribute('data-fields'),
    picked: await veil.getAttribute('data-picked'),
    probe: await veil.getAttribute('data-probe'),
    out: (await page.locator('#aiOut').innerText()).replace(/\s+/g, ' ').trim(),
  }
}

