export default async function run(page) {
  await page.locator('[data-act="aiOpen"]').click()
  await page.waitForTimeout(150)
  await page.locator('[data-note="additional"]').fill('list perks and shift details')
  await page.locator('#aiGo').click()
  await page.waitForTimeout(250)
  return { out: (await page.locator('#aiOut').innerText()).replace(/\s+/g, ' ') }
}

