/* The AI is GIVEN the six context values and is ASKED to write the six prose
   blocks. Only the blocks are checkable — the context comes from the template
   and the Job Info dropdowns, so HR never has to confirm what is already known. */
var AI_FIELDS = ["description","responsibilities","qualifications","additional","instructions","about"];

/** Read-only context the backend always injects, shown so HR can verify it. */
function aiContext(){
  var pos=document.getElementById('pos');
  var posLabel=pos&&pos.selectedOptions.length
    ? pos.selectedOptions[0].text.split(' — ')[0] : "—";
  var deptLabel=pos&&pos.selectedOptions.length
    ? pos.selectedOptions[0].text.split(' — ')[1] : "—";
  var ed=document.getElementById('edu'), ex=document.getElementById('exp');
  return {
    position:posLabel, department:deptLabel,
    skills:STATE.skills.slice(), certs:STATE.certs.slice(),
    education:(ed&&ed.value)||"—", experience:(ex&&ex.value)||"—"
  };
}

function aiRenderContext(){
  var c=aiContext();
  function set(id,html){ var el=document.getElementById(id); if(el) el.innerHTML=html; }
  set('ctxPosition',esc(c.position));
  set('ctxDepartment',esc(c.department));
  set('ctxSkills',c.skills.length?c.skills.map(function(s){
        return '<span class="cg'+(vocabHit(s,VOCAB.skills)?"":" bad")+'">'+esc(s)+'</span>';}).join("")
      :'<span class="muted">none</span>');
  set('ctxCerts',c.certs.length?c.certs.map(function(s){
        return '<span class="cg cert">'+esc(s)+'</span>';}).join("")
      :'<span class="muted">none</span>');
  set('ctxEducation',esc(c.education));
  set('ctxExperience',esc(c.experience));
}

