/** What the AI returns, grounded on the context. Notes steer each block. */
function aiMockResponse(sel){
  var ctx=aiContext();
  var n=sel.notes;
  var lc=/line cook|culinary/i.test(ctx.position);
  var out={};

  if(sel.picked.description){
    var warm=/corporate|formal/i.test(n.description);
    out.description = warm
      ? "We are seeking a "+ctx.position+" to support the "+ctx.department+" team in a structured, professional capacity."
      : "We are looking for a "+ctx.position+" to welcome guests, manage reservations and deliver warm, dependable service at Oxford Suites Makati.";
  }
  if(sel.picked.responsibilities){
    var duties=lc
      ? ["Prepare ingredients according to recipe cards","Maintain food safety and hygiene standards at all times",
         "Coordinate with the kitchen team during service","Keep workstations clean and properly stocked"]
      : ["Welcome and assist hotel guests","Process check-in and check-out procedures",
         "Manage room reservations","Handle guest inquiries and complaints professionally"];
    if(/short|brief|4 lines|fewer/i.test(n.responsibilities)) duties=duties.slice(0,4);
    out.responsibilities=duties.join("\n");
  }
  if(sel.picked.qualifications){
    /* the AI is told to reuse the context skills/certs verbatim */
    var q=[ctx.education==="—"?null:"At least "+ctx.education.replace("Graduate","graduate")+" is preferred"].filter(Boolean);
    ctx.certs.forEach(function(s){ q.push(s); });
    ctx.skills.filter(function(s){return vocabHit(s,VOCAB.skills);}).slice(0,2)
      .forEach(function(s){ q.push(s); });
    if(ctx.experience!=="—") q.push(ctx.experience+" of relevant experience");
    if(/hotel|hospitality/i.test(n.qualifications)) q.push("Previous hotel or hospitality experience is an advantage");
    out.qualifications=q.join("\n");
  }
  if(sel.picked.additional){
    var an=String(n.additional||"");
    var perks=lc
      ? ["Meal provided during shift","Hairnet and apron supplied","Shifting schedule with night differential"]
      : ["Free meal during shift","5-day work week","Uniform provided","13th month pay"];
    if(/skip|without|avoid|no perks/i.test(an)) perks=perks.slice(0,2);
    if(/night|shift|shifting/i.test(an) && !/night differential/i.test(perks.join(" ")))
      perks.unshift("Shifting schedule with night differential");
    out.additional=perks.join("\n");
  }
  if(sel.picked.instructions){
    out.instructions=/walk-?in/i.test(n.instructions)
      ? "Interested applicants may walk in for an interview at the HR Office, Oxford Suites Makati, or send their updated resume through this posting."
      : "Interested applicants may send their updated resume through this posting or walk in for an interview at the HR Office, Oxford Suites Makati.";
  }
  if(sel.picked.about){
    out.about=/short|brief|one sentence/i.test(n.about)
      ? "Oxford Suites Makati is a premier all-suite hotel in the heart of Makati's business district."
      : "Oxford Suites Makati is a premier all-suite hotel in the heart of Makati's business district, known for warm Filipino hospitality and dependable service.";
  }
  return out;
}

/* block id -> the textarea the AI writes into */
var AI_TARGET = {
  description:"t-desc", responsibilities:"t-resp", qualifications:"t-qual",
  additional:"addInfo", instructions:"t-instr", about:"t-about"
};
var AI_LABEL = {
  description:"Job Description", responsibilities:"Key Responsibilities",
  qualifications:"Qualifications", additional:"Additional Info",
  instructions:"Application Instruction", about:"About Company"
};

input.oldString:
/** What the AI returns. Deliberately includes one term that is NOT in the
 *  vocabulary, so the grounding report has something real to say. */
function aiMockResponse(sel){
  var key=STATE.pos||"fdo";
  var n=sel.notes;
  var out={};

  if(sel.picked.skills){
    var base = key==="lc"
      ? ["Food Safety","Knife Skills","Plating"]
      : ["Front Office Operations","Guest Relations","Complaint Handling","Scheduling"];
    /* the notes box steers the mock the way it would steer the real model.
       Negations are stripped first, so "skip anything technical" does not read
       as a request FOR technical skills. */
    var sn=String(n.skills||"").replace(/\b(skip|avoid|without|no|not|never|don'?t)\b[^,.;]*/gi," ");
    if(/technical|software|excel|ms office|computer/i.test(sn))
      base=["MS Office","Time Management","Scheduling"];
    else if(/guest|service|front|hospitality/i.test(sn))
      base=["Customer Service","Guest Relations","Complaint Handling","Front Office Operations"];
    /* one invented term, to demonstrate skills_new */
    out.skills=base.concat(["Service Upselling"]);
  }
  if(sel.picked.certificate){
    out.certs = key==="lc" ? ["TESDA NC II Cookery","Food Handler Certificate"] : ["TESDA NC II Front Office"];
  }
  if(sel.picked.education){
    out.edu = /any bachelor|accept any/i.test(n.education) ? "Bachelor's Degree" : "College Level";
  }
  if(sel.picked.experience){
    out.exp = /hotel experience|strongly preferred/i.test(n.experience) ? "3-5 Years" : "1-2 Years";
  }
  /* Additional Info is free prose — no vocabulary grounding, nothing is scored
     from it. The notes box only narrows what may be promised. */
  if(sel.picked.additional){
    var an=String(n.additional||"");
    var perks = ["Free meal during shift","5-day work week","Uniform provided",
                 "13th month pay","Night differential"];
    if(/skip|without|avoid|no perks/i.test(an)) perks=perks.slice(0,2);
    if(/night|shift|shifting/i.test(an)) perks.unshift("Shifting schedule with night differential");
    out.additional = (key==="lc" ? ["Meal provided during shift","Hairnet and apron supplied"] : perks).join("\n");
  }
  out.positionNote = n.position ? "Position guidance applied: "+n.position : "";
  out.deptNote    = n.department ? "Department guidance applied: "+n.department : "";
  return out;
}

