function aiGenerate(){
  var sel=aiSelection();
  if(!AI_FIELDS.some(function(f){return sel.picked[f];})) return;

  var res=aiMockResponse(sel);
  var ctx=aiContext();
  var rows=[];

  /* write each generated block into the block it belongs to */
  AI_FIELDS.forEach(function(f){
    if(!sel.picked[f] || !res[f]) return;
    var box=document.getElementById(AI_TARGET[f]);
    if(!box) return;
    var text=String(res[f]).trim();
    if(!text) return;

    /* merge line-by-line so regenerating never duplicates what HR kept */
    var have={};
    toLines(box.value).forEach(function(l){ have[l.toLowerCase()]=1; });
    var incoming=toLines(text);
    var added=incoming.filter(function(l){ return !have[l.toLowerCase()]; });
    if(added.length) box.value=toLines(box.value).concat(added).join("\n");

    /* the vocabulary report only applies to the prose blocks that quote terms */
    var quoted=added.filter(function(l){
      return AI_FIELDS.indexOf(f)!==-1 && vocabHit(l,VOCAB.skills);
    });
    var freshTerms=added.filter(function(l){
      return /\b(skill|proficiency|experience with|knowledge of)\b/i.test(l) && !vocabHit(l,VOCAB.skills);
    });

    rows.push({k:AI_LABEL[f],
      v:added.length+" line"+(added.length===1?"":"s")+" written"
        +(box.value!==text?" &middot; existing text kept":"")});
    if(quoted.length){
      rows[rows.length-1].list=quoted.map(function(l){
        return "&#10003; reused a term from your skills &rarr; <b>"+esc(vocabHit(l,VOCAB.skills))+"</b>";});
    }
    if(freshTerms.length){
      rows[rows.length-1].list=(rows[rows.length-1].list||[]).concat(freshTerms.map(function(l){
        return "&#9679; "+esc(l)+" <span class='muted'>&mdash; not a vocabulary term, scores 0</span>";}));
    }
  });

  aiRenderContext();

  var html=rows.length
    ? rows.map(function(r){
        return '<div class="r"><span class="k">'+esc(r.k)+'</span><span class="v">'+r.v
          +(r.list&&r.list.length?'<ul>'+r.list.map(function(li){return "<li>"+li+"</li>";}).join("")+"</ul>":"")
          +'</span></div>';}).join("")
    : '<div class="r"><span class="v muted">Nothing was generated.</span></div>';

  html+='<div class="r" style="margin-top:6px"><span class="k">Grounded on</span><span class="v muted">'
    +esc(ctx.position)+' &middot; '+esc(ctx.department)+' &middot; '+ctx.skills.length+' skills &middot; '
    +ctx.certs.length+' cert'+(ctx.certs.length===1?"":"s")+' &middot; '+esc(ctx.education)+' &middot; '+esc(ctx.experience)
    +'</span></div>';
  html+='<div class="r"><span class="k">Generated</span><span class="v muted">'
    +(AI_FIELDS.filter(function(f){return sel.picked[f];}).map(function(f){return AI_LABEL[f];}).join(", ")||"nothing")
    +'</span></div>';
  html+='<div class="r"><span class="k">Left alone</span><span class="v muted">'
    +(AI_FIELDS.filter(function(f){return !sel.picked[f];}).map(function(f){return AI_LABEL[f];}).join(", ")||"nothing")
    +'</span></div>';

  var out=document.getElementById("aiOut");
  out.innerHTML=html;
  out.classList.add("on");

  var m=document.getElementById("aiMeter");
  if(m){
    var i=m.querySelectorAll("i");
    [].forEach.call(i,function(el,idx){ el.className = idx<3 ? "used full" : ""; });
  }
  toast("<b>AI draft ready</b> &mdash; "+rows.length+" block"+(rows.length===1?"":"s")
    +" written from your "+esc(ctx.position)+" requirements.","good");
}

input.oldString:
function aiGenerate(){
  var sel=aiSelection();
  if(!AI_FIELDS.some(function(f){return sel.picked[f];})) return;

  var res=aiMockResponse(sel);
  var rows=[], fresh=[];

  /* apply to the draft exactly where each value belongs */
  if(res.skills){
    var addedSk=[],matchedSk=[],haveSk={};
    STATE.skills.forEach(function(x){ haveSk[x.toLowerCase()]=1; });
    res.skills.forEach(function(s){
      var c=vocabHit(s,VOCAB.skills);
      /* dedupe on BOTH branches — an unknown term must not be re-appended on
         every run, or repeated clicks pile up duplicates */
      var key=(c||s).toLowerCase();
      if(!haveSk[key]){ addedSk.push(c||s); haveSk[key]=1; }
      if(c) matchedSk.push(c); else fresh.push(s);
    });
    if(addedSk.length) STATE.skills=STATE.skills.concat(addedSk);
    rows.push({k:"Skills",v:addedSk.length+" added to Screening Requirements",
      list:addedSk.map(function(s){
        return vocabHit(s,VOCAB.skills)
          ? "&#10003; "+esc(s)+" <span class='muted'>(already in vocabulary)</span>"
          : "&#9679; "+esc(s)+" <span class='muted'>&mdash; new, press + to add to the vocabulary</span>";
      })});
  }
  if(res.certs && res.certs.length){
    var addedC=[],haveC={};
    STATE.certs.forEach(function(x){ haveC[x.toLowerCase()]=1; });
    res.certs.forEach(function(c){
      if(!haveC[c.toLowerCase()]){ addedC.push(c); haveC[c.toLowerCase()]=1; }
    });
    STATE.certs=STATE.certs.concat(addedC);
    rows.push({k:"Certificates",v:addedC.length+" added"});
  }
  if(res.edu && sel.picked.education){
    STATE.edu=res.edu;
    var e=document.getElementById("edu"); if(e) e.value=res.edu;
    rows.push({k:"Education",v:esc(res.edu)});
  }
  if(res.exp && sel.picked.experience){
    STATE.exp=res.exp;
    var x2=document.getElementById("exp"); if(x2) x2.value=res.exp;
    rows.push({k:"Experience",v:esc(res.exp)});
  }
  if(res.additional && sel.picked.additional){
    var box=document.getElementById("addInfo");
    if(box){
      /* dedupe on append — a second Generate must not stack the same perks */
      var have={};
      toLines(box.value).forEach(function(l){ have[l.toLowerCase()]=1; });
      var freshLines=res.additional.split("\n").map(function(s){ return s.trim(); })
        .filter(function(s){ return s && !have[s.toLowerCase()]; });
      if(freshLines.length) box.value=toLines(box.value).concat(freshLines).join("\n");
      rows.push({k:"Additional Info",
        v:freshLines.length?freshLines.length+" line(s) added to the block":"already present, nothing new",
        list:freshLines.map(function(s){
          return "&#183; "+esc(s)+" <span class='muted'>&mdash; prose, not scored</span>";})});
    }
  }

  render();

  /* the grounding report — the whole point of passing the vocabulary in */
  var html=rows.map(function(r){
    return '<div class="r"><span class="k">'+esc(r.k)+'</span><span class="v">'+r.v
      +(r.list?'<ul>'+r.list.map(function(li){return "<li>"+li+"</li>";}).join("")+"</ul>":"")
      +'</span></div>';
  }).join("");

  html+='<div class="r" style="margin-top:6px"><span class="k">Sent to AI</span><span class="v muted">'
    +(AI_FIELDS.filter(function(f){return sel.picked[f];}).join(", ")||"nothing")
    +'</span></div>';
  html+='<div class="r"><span class="k">Skipped</span><span class="v muted">'
    +(AI_FIELDS.filter(function(f){return !sel.picked[f];}).join(", ")||"nothing")
    +'</span></div>';

  var out=document.getElementById("aiOut");
  out.innerHTML=html;
  out.classList.add("on");

  var m=document.getElementById("aiMeter");
  if(m){
    var i=m.querySelectorAll("i");
    [].forEach.call(i,function(el,idx){ el.className = idx<3 ? "used full" : ""; });
  }
  toast(fresh.length
    ? "<b>AI draft ready</b> — "+fresh.length+" term(s) not in your vocabulary. Add them with + so resumes match."
    : "<b>AI draft ready</b> — every generated term is already in your vocabulary.",
    fresh.length?"warn":"good");
}

