export default async function run(page) {
  const out = {}
  const flat = (s) => (s || '').replace(/\s+/g, ' ').trim()
  const count = (s) => page.locator(s).count()
  const val = (id) => page.locator(id).inputValue()
  const txt = (id) => flat(await page.locator(id).innerText())

  await page.locator('[data-act="aiOpen"]').click()
  await page.waitForTimeout(200)

  // ---- checklist is the 6 content blocks ----
  out.checklistLabels = await page.locator('#aiVeil .cb span').allInnerTexts()
  out.contextLabels = await page.locator('#aiVeil .kv .k').allInnerTexts()

  // ---- context shows the live values ----
  out.context = {
    position: await txt('#ctxPosition'),
    department: await txt('#ctxDepartment'),
    skills: await txt('#ctxSkills'),
    certs: await txt('#ctxCerts'),
    education: await txt('#ctxEducation'),
    experience: await txt('#ctxExperience'),
  }

  // ---- generate all six ----
  await page.locator('#aiGo').click()
  await page.waitForTimeout(250)
  out.report = flat(await page.locator('#aiOut').innerText())
  out.blocks = {
    description: await val('#t-desc'),
    responsibilities: (await val('#t-resp')).split('\n').length,
    qualifications: (await val('#t-qual')).split('\n').length,
    additional: (await val('#addInfo')).split('\n').length,
    instructions: await val('#t-instr'),
    about: await val('#t-about'),
  }

  // ---- untick all six -> disabled ----
  for (const f of ['description','responsibilities','qualifications','additional','instructions','about']) {
    await page.locator(`[data-ai="${f}"]`).uncheck()
  }
  out.allUnchecked = { disabled: await page.locator('#aiGo').isDisabled(), dimmed: await count('#aiVeil .airow.off') }

  // ---- only Qualifications ----
  await page.locator('[data-ai="qualifications"]').check()
  const before = await val('#t-qual')
  await page.locator('#aiGo').click()
  await page.waitForTimeout(200)
  out.onlyQual = {
    report: flat(await page.locator('#aiOut').innerText()),
    qualUnchangedOrGrown: (await val('#t-qual')).length >= before.length,
    othersUntouched: (await val('#t-resp')).split('\n').length === out.blocks.responsibilities,
  }

  // ---- notes steer the block ----
  await page.locator('[data-note="responsibilities"]').fill('keep it to 2 lines only')
  await page.locator('[data-ai="responsibilities"]').check()
  await page.locator('#aiGo').click()
  await page.waitForTimeout(200)
  out.notesSteer = { resp: await val('#t-resp') }

  // ---- context reflects the education dropdown ----
  await page.locator('#edu').selectOption({ label: 'Master\u2019s Degree' }).catch(async () => {
    await page.locator('#edu').selectOption({ index: 3 })
  })
  await page.locator('[data-act="aiOpen"]').click().catch(() => {})
  await page.waitForTimeout(200)
  out.ctxAfterChange = { education: await txt('#ctxEducation') }

  return out
}

export default async function run(page) {
  const out = {}
  const flat = (s) => (s || '').replace(/\s+/g, ' ').trim()
  const count = (s) => page.locator(s).count()
  const val = async (id) => page.locator(id).inputValue()
  const txt = async (id) => flat(await page.locator(id).innerText())

  await page.locator('[data-act="aiOpen"]').click()
  await page.waitForTimeout(200)

