    respLines: (await val('#t-resp')).split('\n').length,
    qualLines: (await val('#t-qual')).split('\n').length,
    addLines: (await val('#addInfo')).split('\n').length,
    instr: await txt('#t-instr'),
    about: await txt('#t-about'),
  }

  for (const f of ['description','responsibilities','qualifications','additional','instructions','about']) {
    await page.locator(`[data-ai="${f}"]`).uncheck()
  }
  out.allUnchecked = { disabled: await page.locator('#aiGo').isDisabled(), dimmed: await count('#aiVeil .airow.off') }

  const respBefore = await val('#t-resp')
  await page.locator('[data-ai="qualifications"]').check()
  await page.locator('#aiGo').click()
  await page.waitForTimeout(200)
  out.onlyQual = {
    report: flat(await page.locator('#aiOut').innerText()),
    respUntouched: (await val('#t-resp')) === respBefore,
  }

  await page.locator('[data-note="responsibilities"]').fill('keep it to 2 lines only')
  await page.locator('[data-ai="responsibilities"]').check()
  await page.locator('#aiGo').click()
  await page.waitForTimeout(200)
  out.notesSteer = { resp: await txt('#t-resp') }

  await page.locator('#edu').selectOption({ index: 3 })
  await page.waitForTimeout(150)
  await page.locator('[data-act="aiOpen"]').click().catch(() => {})
  await page.waitForTimeout(200)
  out.ctxEducationAfter = await txt('#ctxEducation')

  return out
}

