export default async function run(page) {
  const out = {}
  const flat = (s) => (s || '').replace(/\s+/g, ' ').trim()
  const count = (s) => page.locator(s).count()
  const confirmOpen = () => page.locator('#veil').evaluate((e) => e.classList.contains('on'))

  out.location = {
    insidePanel: await page.locator('.block.active #pos').count(),
    posRow: await count('.posrow'),
    headerClean: !(await page.locator('#panelTop #pos').count()),
  }

  // switching with skills present must ASK first
  await page.locator('#pos').selectOption('lc')
  await page.waitForTimeout(250)
  out.askFirst = {
    confirmOpen: await confirmOpen(),
    template: flat(await page.locator('#dlgTpl').innerText()),
    diff: flat(await page.locator('#dlgDiff').innerText()),
  }

  // accept -> template applied
  await page.locator('.dlg .btn').last().click()
  await page.waitForTimeout(300)
  out.accepted = {
    confirmOpen: await confirmOpen(),
    banner: flat(await page.locator('#tplBanner').innerText()),
    srcTag: flat(await page.locator('#srcTag').innerText()),
    edu: await page.locator('#edu').inputValue(),
    exp: await page.locator('#exp').inputValue(),
    chips: await count('#skillChips .chip'),
    certs: await count('#certChips .chip'),
    gate: flat(await page.locator('#gate').innerText()),
  }

  // no-template position -> no dialog, honest empty state, skills kept
  await page.locator('#pos').selectOption('hr')
  await page.waitForTimeout(250)
  out.noTemplate = {
    confirmOpen: await confirmOpen(),
    srcTag: flat(await page.locator('#srcTag').innerText()),
    banner: flat(await page.locator('#tplBanner').innerText()),
    chipsKept: await count('#skillChips .chip'),
  }

  // back to a templated position
  await page.locator('#pos').selectOption('fdo')
  await page.waitForTimeout(250)
  out.askAgain = { confirmOpen: await confirmOpen() }
  await page.locator('.dlg .btn.ghost').click()
  await page.waitForTimeout(250)
  out.cancelled = {
    confirmOpen: await confirmOpen(),
    banner: flat(await page.locator('#tplBanner').innerText()),
  }

  // AI modal reads the dropdown from its new home
  await page.locator('[data-act="aiOpen"]').click()
  await page.waitForTimeout(250)
  out.aiContext = {
    open: await page.locator('#aiVeil').evaluate((e) => e.classList.contains('on')),
    position: flat(await page.locator('#ctxPosition').innerText()),
    department: flat(await page.locator('#ctxDepartment').innerText()),
    education: flat(await page.locator('#ctxEducation').innerText()),
    skills: (await count('#ctxSkills .cg')),
  }

  return out
}

