556:   const recognized = new Map<string, string>();
557:   const unrecognized: string[] = [];
558:   const seenUnrecognized = new Set<string>();
559:   rawLines.forEach((raw) => {
560:     const line = raw.trim();
561:     if (!line) return;
562:     const hits = new Set<string>();
563:     const whole = canonicalizeBuilderEntity(line, index);
564:     if (whole) hits.add(whole);
565:     const padded = ` ${normalizeEntityText(line)} `;
566:     index.keys.forEach((key) => {
567:       if (key.length >= 4 && padded.includes(` ${key} `)) {
568:         const canonical = index.exact.get(key);
569:         if (canonical) hits.add(canonical);
570:       }
571:     });
572:     if (hits.size === 0) {
573:       const key = normalizeEntityText(line);
574:       if (!seenUnrecognized.has(key)) {
575:         seenUnrecognized.add(key);
576:         unrecognized.push(line);
577:       }
578:     } else {
