    setBlocks((b) => [...b, ...AI_CONTENT_BLOCKS.filter((id) => !b.includes(id))]);
    setActiveBlock("description");
    if (res.meta?.usage) setAiUsage(res.meta.usage);
    const fresh = res.meta?.skills_new ?? [];
    const via = res.meta?.generated_via;
